<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import {Check,LoaderCircle,NotebookPen,X} from 'lucide-vue-next'
import {api,saveRow,state} from '../api'
import {recordDrafts} from '../drafts'
import {shanghaiDate} from '../types'
import type {Row} from '../types'
import {cleanJournal,emptyFacets,journalCategories,journalDuration,journalPeriods,taskStatuses} from '../journal'
import type {JournalFacets} from '../journal'
import TagInput from './TagInput.vue'
const props=defineProps<{row?:Row;preset?:Record<string,any>;date?:string}>()
const emit=defineEmits<{close:[];saved:[row:Row,collection:string];refresh:[]}>()
const draftKey=`journal:${props.row?.id||props.date||'new'}:${props.preset?.category||''}:${props.preset?.taskId||''}`
const draft=recordDrafts[draftKey],facets=ref<JournalFacets>(emptyFacets()),saveBase=ref<Row|undefined>(draft?.base||(draft?.form?.version?draft.form:props.row))
const makeForm=()=>({id:crypto.randomUUID(),title:'',content:'',category:'LIFE',startDate:props.date||shanghaiDate(),endDate:'',timeMode:'DATE',period:'AFTERNOON',startTime:'',endTime:'',durationMinutes:null,place:'',people:[] as string[],tags:[] as string[],taskId:'',...props.row,...props.preset})
const originalForm=makeForm(),baseline=ref(JSON.stringify(originalForm))
const form=reactive<Record<string,any>>(draft?.form||originalForm)
const closePrompt=ref(false),dirty=computed(()=>JSON.stringify(form)!==baseline.value)
const saving=ref(false),error=ref(''),savedNote=ref(''),submitted=ref(false),details=ref(!!props.row||!!props.preset?.taskId||['WORK','STUDY'].includes(form.category)),taskSearch=ref(''),taskLoadError=ref('')
const people=computed(()=>Array.isArray(form.people)?form.people:[]),tags=computed(()=>Array.isArray(form.tags)?form.tags:[])
const taskChoices=computed(()=>facets.value.tasks)
const exactDuration=computed(()=>form.timeMode==='EXACT'&&!!form.startTime&&!!form.endTime)
const durationUnit=ref('minutes')
const durationAmount=computed({get:()=>form.durationMinutes==null?'':Number(form.durationMinutes)/(durationUnit.value==='hours'?60:1),set:(value:number|string)=>{if(value===''){form.durationMinutes=null;return}const minutes=Number(value)*(durationUnit.value==='hours'?60:1),rounded=Math.round(minutes);form.durationMinutes=Number.isFinite(minutes)&&Math.abs(minutes-rounded)<1e-8?rounded:minutes}})
const automaticDuration=computed(()=>journalDuration(form as Row))
const titlePlaceholder=computed(()=>({MEAL:'例如：和小王在东门吃牛肉面',WORK:'例如：修好登录接口，联调待继续',STUDY:'例如：高等数学，导数与微分',TRAVEL:'例如：去杭州出差',SOCIAL:'例如：和朋友看电影'} as Record<string,string>)[form.category]||'简单记下做了什么')
let taskRequest=0,taskTimer:ReturnType<typeof setTimeout>|undefined
async function loadFacets(q=''){const request=++taskRequest;try{const data=await api<JournalFacets>('/journal/facets'+(q?'?q='+encodeURIComponent(q):''));if(request!==taskRequest)return;facets.value=data;if(form.taskId&&!data.tasks.some(t=>t.id===form.taskId)){try{const linked=await api<Row>('/data/tasks/'+form.taskId);if(request===taskRequest)facets.value.tasks=[linked,...facets.value.tasks]}catch{taskLoadError.value='关联待办暂时无法读取，保存时会保留原关联。'}}}catch{taskLoadError.value='常用内容暂时无法读取，你仍可以手动填写。'}}
function findTasks(){clearTimeout(taskTimer);taskTimer=setTimeout(()=>loadFacets(taskSearch.value),250)}
onMounted(()=>loadFacets())
onBeforeUnmount(()=>{clearTimeout(taskTimer);taskRequest++;if(!submitted.value&&dirty.value&&state.authenticated)recordDrafts[draftKey]={form:JSON.parse(JSON.stringify(form)),base:saveBase.value?JSON.parse(JSON.stringify(saveBase.value)):undefined}})
function close(){if(saving.value)return;if(dirty.value)closePrompt.value=true;else emit('close')}
function discard(){submitted.value=true;delete recordDrafts[draftKey];emit('close')}
async function submit(again=false){
 if(saving.value)return
 error.value='';savedNote.value=''
 if(!String(form.title||'').trim()){error.value='请用一句话记下做了什么。';return}
 if(!form.startDate||form.startDate>shanghaiDate()||(form.endDate&&form.endDate>shanghaiDate())){error.value='实际记录请填写今天或更早的日期，未来安排可以添加为待办。';return}
 if(form.endDate&&form.endDate<form.startDate){error.value='结束日期不能早于开始日期。';return}
 if(form.timeMode==='EXACT'&&!form.startTime){error.value='请填写开始时间，或切换到只记日期、常用时段。';return}
 if(!exactDuration.value&&form.durationMinutes!=null&&(!Number.isInteger(Number(form.durationMinutes))||Number(form.durationMinutes)<1||Number(form.durationMinutes)>10080)){error.value='投入时长请填写 1～10080 分钟；可以切换小时填写。';return}
 saving.value=true
 try{const fields=cleanJournal(form);if(exactDuration.value)fields.durationMinutes=null;fields.people=people.value;fields.tags=tags.value;if(form.timeMode!=='PERIOD')fields.period=null;if(form.timeMode!=='EXACT'){fields.startTime=null;fields.endTime=null}const row=await saveRow('journal',fields,saveBase.value);delete recordDrafts[draftKey];if(again&&!saveBase.value){const keepDate=form.startDate;Object.assign(form,makeForm(),{id:crypto.randomUUID(),startDate:keepDate,title:'',content:'',people:[],place:'',taskId:'',tags:[],endDate:'',durationMinutes:null});baseline.value=JSON.stringify(form);savedNote.value='已保存，可以继续记下一件事。';emit('refresh')}else{submitted.value=true;emit('saved',row,'journal')}}catch(e){error.value=(e as Error).message}finally{saving.value=false}
}
</script>
<template><div class="overlay" @click.self="close"><section class="drawer journal-editor" role="dialog" aria-modal="true" :aria-label="row?'编辑生活记录':'记一件事'"><header class="drawer-header"><div class="heading-with-icon"><NotebookPen :size="23"/><div><small>LIFE JOURNAL</small><h2>{{row?'编辑生活记录':'记一件事'}}</h2></div></div><button class="icon-button" title="暂时关闭生活记录" :disabled="saving" @click="close"><X :size="20"/></button></header><form class="drawer-form" @submit.prevent="submit()" @keydown.ctrl.enter.prevent="submit()" @keydown.meta.enter.prevent="submit()"><div class="drawer-body"><p class="hint">日期和一句话就能保存，其余按需要补充。</p><p v-if="draft" class="hint">已恢复本次解锁期间的草稿。</p><div class="fields-grid"><label class="field full"><span>做了什么 *</span><input v-model="form.title" maxlength="500" required :placeholder="titlePlaceholder" autofocus/></label><label class="field"><span>发生日期 *</span><input v-model="form.startDate" type="date" :max="shanghaiDate()" required/></label><label class="field"><span>结束日期 · 跨日选填</span><input v-model="form.endDate" type="date" :min="form.startDate" :max="shanghaiDate()"/></label><label class="field"><span>分类</span><select v-model="form.category"><option v-for="(label,key) in journalCategories" :key="key" :value="key">{{label}}</option></select></label><label class="field"><span>时间记得多具体</span><select v-model="form.timeMode"><option value="DATE">只记日期</option><option value="PERIOD">常用时段</option><option value="EXACT">具体时间</option></select></label><label v-if="form.timeMode==='PERIOD'" class="field full"><span>发生时段</span><select v-model="form.period"><option v-for="(label,key) in journalPeriods" :key="key" :value="key">{{label}}</option></select></label><template v-if="form.timeMode==='EXACT'"><label class="field"><span>开始时间 *</span><input v-model="form.startTime" type="time" required/></label><label class="field"><span>结束时间 · 选填</span><input v-model="form.endTime" type="time"/></label></template><div class="duration-fields full"><template v-if="exactDuration"><span>本次投入时长</span><strong>{{automaticDuration||'请检查起止日期和时间'}}</strong><p class="hint">根据完整起止时间自动计算。</p></template><template v-else><label class="field"><span>本次投入时长 · 选填</span><input v-model.number="durationAmount" type="number" min="0" :max="durationUnit==='hours'?168:10080" :step="durationUnit==='hours'?'any':1" aria-label="本次投入时长" placeholder="不确定可以留空"/></label><label class="field duration-unit"><span>单位</span><select v-model="durationUnit" aria-label="投入时长单位"><option value="minutes">分钟</option><option value="hours">小时</option></select></label><p class="hint">事后补记也能填投入时长；单日不超过 24 小时，跨日请填写结束日期。</p></template></div><label class="field full"><span>{{form.category==='MEAL'?'吃了什么、想补充的细节':form.category==='STUDY'?'课程内容与笔记':form.category==='WORK'?'做到了哪里、还有什么要做':'详细内容 · 选填'}}</span><textarea v-model="form.content" rows="3" maxlength="10000" placeholder="可以记过程、结果，也可以留空。"/></label></div><TagInput :model-value="tags" @update:model-value="form.tags=$event" label="标签" :suggestions="facets.tags.map(t=>t.name)"/><div class="people-place"><TagInput :model-value="people" @update:model-value="form.people=$event" label="和谁 · 可填多人" :tags="false" :suggestions="facets.people"/><label class="field"><span>地点</span><input v-model="form.place" maxlength="500" list="journal-places" placeholder="在哪里"/><datalist id="journal-places"><option v-for="place in facets.places" :key="place" :value="place"/></datalist></label></div><button type="button" class="text-link task-link-toggle" @click="details=!details">{{details?'收起关联待办':'关联待办 / 记录工作进展'}}</button><div v-if="details" class="task-link-fields"><label class="field"><span>查找待办</span><input v-model="taskSearch" @input="findTasks" placeholder="输入任务关键词"/></label><label class="field"><span>这条记录属于哪个任务</span><select v-model="form.taskId"><option value="">不关联</option><option v-for="task in taskChoices" :key="task.id" :value="task.id">{{task.title}} · {{task.deleted?'已移入回收站':taskStatuses[task.status]||'待办'}}</option></select></label><p class="hint">关联后会汇总到这个待办的累计投入；可以补记已完成任务的工作或学习。</p></div><p v-if="taskLoadError" class="hint">{{taskLoadError}}</p><p class="hint draft-hint">暂时关闭会保留当前草稿；锁定或刷新页面后清除。Ctrl / ⌘ + Enter 可保存。</p><p v-if="savedNote" class="saved-note" role="status">{{savedNote}}</p><p v-if="error" class="error-box" role="alert">{{error}}</p></div><footer class="drawer-footer"><button type="button" class="button secondary" :disabled="saving" @click="close">暂时关闭</button><button v-if="!row" type="button" class="button secondary" :disabled="saving" @click="submit(true)">保存并再记</button><button class="button primary" :disabled="saving"><LoaderCircle v-if="saving" class="spin" :size="16"/><Check v-else :size="16"/>{{saving?'正在保存':'保存记录'}}</button></footer></form></section><div v-if="closePrompt" class="overlay centered" @click.self="closePrompt=false"><section class="modal draft-confirm" role="alertdialog" aria-modal="true" aria-label="保留未保存的草稿"><h2>这条记录还没有保存</h2><p>可以保留草稿后关闭，稍后继续。草稿仅保留在本次解锁期间。</p><footer><button class="button secondary" @click="closePrompt=false">继续填写</button><button class="button secondary" @click="discard">放弃草稿</button><button class="button primary" @click="emit('close')">保留并关闭</button></footer></section></div></div></template>
<style scoped>.duration-fields{grid-column:1/-1;display:grid;grid-template-columns:minmax(0,1fr) 95px;gap:0 12px;background:var(--input);border:1px solid var(--border);border-radius:8px;padding:11px 12px;margin:0 0 14px}.duration-fields>.field{margin:0!important}.duration-fields>.hint{grid-column:1/-1;margin:7px 0 0}.duration-fields>span{font-size:11px;color:var(--muted);grid-column:1/-1}.duration-fields>strong{grid-column:1/-1;font-size:15px;font-weight:500;margin-top:5px}.duration-fields .duration-unit{min-width:0}.draft-confirm{max-width:450px}.draft-confirm h2{font-size:18px}.draft-confirm p{font-size:12px;line-height:1.8}.draft-confirm footer{flex-wrap:wrap}.draft-confirm .button{font-size:11px;padding:9px 12px}.journal-editor{width:min(560px,100vw)}.journal-editor .drawer-header{padding:20px 23px}.journal-editor .drawer-header h2{font-size:20px}.journal-editor .drawer-body{padding:20px 23px}.journal-editor .drawer-footer{padding:14px 23px;gap:8px}.journal-editor .drawer-footer .button{font-size:11px;padding:10px 12px}.journal-editor .field{margin-bottom:14px}.journal-editor .field>span{font-size:11px;margin-bottom:7px}.journal-editor .field input,.journal-editor .field select,.journal-editor .field textarea{font-size:12px;padding:10px 11px;min-height:40px}.journal-editor .hint{font-size:11px;line-height:1.8}.people-place{display:grid;grid-template-columns:1fr 1fr;gap:14px}.task-link-toggle{font-size:11px;margin:0 0 14px}.task-link-fields{padding:13px;border:1px solid var(--border);border-radius:8px;background:var(--input);margin-bottom:14px}.task-link-fields .hint{margin:0}.draft-hint{margin:12px 0 0;color:var(--muted)}.saved-note{font-size:12px;color:var(--mint)}@media(max-width:580px){.journal-editor .drawer-body,.journal-editor .drawer-header{padding:18px}.journal-editor .drawer-footer{padding:12px 18px}.people-place{grid-template-columns:1fr;gap:0}}</style>
